/* V0.4.3: project-owned manual progress, with explicit weights and completion.
   Not inferred from job counts, dates, or customer publication. Local demo only. */
const id=()=> 'step-'+Math.random().toString(36).slice(2,11);
const validProject=(s,pid)=>{if(!s.projects?.some(p=>p.id===pid&&!p.archivedAt))throw Error('Active project not found');};
const basis=(value,label)=>{
 const n=Number(value);
 if(!Number.isFinite(n)||n<0||n>100)throw Error(label+' must be between 0 and 100');
 const bp=Math.round(n*100);
 if(Math.abs(n*100-bp)>0.00000001)throw Error(label+' supports up to two decimal places');
 return bp;
};
const name=str=>{const v=String(str||'').trim();if(!v||v.length>140)throw Error('Progress step title must be 1–140 characters');return v;};
const now=()=>new Date().toISOString();
export function ensureProgress(s){
 if(!Array.isArray(s.projectProgressSteps))s.projectProgressSteps=[];
 s.progressSchemaVersion=1;
 return s;
}
export function projectSteps(s,projectId){
 ensureProgress(s);
 return s.projectProgressSteps.filter(x=>x.projectId===projectId&&!x.archivedAt)
  .sort((a,b)=>(a.order||0)-(b.order||0)||a.id.localeCompare(b.id));
}
export function progressSnapshot(s,projectId){
 validProject(s,projectId);
 const steps=projectSteps(s,projectId);
 const totalBasis=steps.reduce((n,x)=>n+x.weightBp,0);
 const earnedBasis=Math.round(steps.reduce((n,x)=>n+x.weightBp*x.doneBp,0)/10000);
 return {projectId,configured:steps.length>0,count:steps.length,
   weightTotal:totalBasis/100,unassigned:Math.max(0,10000-totalBasis)/100,
   earned:earnedBasis/100,
   completed:steps.filter(x=>x.doneBp===10000).length,
   partial:steps.filter(x=>x.doneBp>0&&x.doneBp<10000).length,
   outstanding:steps.length-steps.filter(x=>x.doneBp===10000).length,
   fullyWeighted:totalBasis===10000};
}
export function saveProgressStep(s,{projectId,id:existingId,title,weight,completion}){
 ensureProgress(s);validProject(s,projectId);
 const existing=existingId?s.projectProgressSteps.find(x=>x.id===existingId&&!x.archivedAt):null;
 if(existingId&&!existing)throw Error('Progress step not found');
 if(existing&&existing.projectId!==projectId)throw Error('Progress step belongs to another project');
 if(!existing&&projectSteps(s,projectId).length>=1000)throw Error('Maximum 1,000 active progress steps per project');
 const w=basis(weight,'Weight'),done=basis(completion,'Completion'),label=name(title);
 const oldWeight=existing?.weightBp||0;
 const allocation=projectSteps(s,projectId).reduce((n,x)=>n+x.weightBp,0)-oldWeight+w;
 if(allocation>10000)throw Error('Assigned progress weights exceed 100%; reduce another step first');
 if(existing){Object.assign(existing,{title:label,weightBp:w,doneBp:done,updatedAt:now()});return existing;}
 const current=projectSteps(s,projectId);
 const row={id:id(),projectId,title:label,weightBp:w,doneBp:done,
  order:(current.at(-1)?.order||0)+1,createdAt:now()};
 s.projectProgressSteps.push(row);
 return row;
}
export function archiveProgressStep(s,{projectId,stepId,restore=false}){
 ensureProgress(s);validProject(s,projectId);
 const row=s.projectProgressSteps.find(x=>x.projectId===projectId&&x.id===stepId);
 if(!row)throw Error('Progress step not found');
 if(restore){
   if(!row.archivedAt)throw Error('Progress step is already active');
   if(projectSteps(s,projectId).length>=1000)throw Error('Maximum 1,000 active progress steps');
   const total=projectSteps(s,projectId).reduce((v,x)=>v+x.weightBp,0);
   if(total+row.weightBp>10000)throw Error('Restoration would exceed 100% weighting');
   delete row.archivedAt;
 }else{
   if(row.archivedAt)throw Error('Already removed');
   row.archivedAt=now();
 }
 return row;
}
export function generateProgressSteps(s,{projectId,count,prefix='Step'}){
 ensureProgress(s);validProject(s,projectId);
 const n=Number(count),existing=projectSteps(s,projectId).length;
 if(!Number.isSafeInteger(n)||n<1||n>1000||existing+n>1000)throw Error('Choose a number of steps that keeps the project at 1,000 or fewer');
 const label=name(prefix);
 const last=projectSteps(s,projectId).at(-1)?.order||0;
 const stamp=now();
 const created=Array.from({length:n},(_,i)=>({id:id(),projectId,title:label+' '+(existing+i+1),
  weightBp:0,doneBp:0,order:last+i+1,createdAt:stamp}));
 s.projectProgressSteps.push(...created);
 return created;
}
export function importProgressSteps(s,{projectId,lines}){
 ensureProgress(s);validProject(s,projectId);
 const list=String(lines||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
 if(!list.length||list.length+projectSteps(s,projectId).length>1000)throw Error('Import must contain 1–1,000 steps within the project limit');
 // title | weight % | completion %, title|weight and title-only lines also accepted.
 const parsed=list.map(line=>{
   const a=line.split('|').map(x=>x.trim());
   if(a.length>3)throw Error('Use: Step title | weight % | completion %');
   return {title:name(a[0]),weightBp:basis(a[1]||0,'Weight'),doneBp:basis(a[2]||0,'Completion')};
 });
 const current=projectSteps(s,projectId),total=current.reduce((n,x)=>n+x.weightBp,0)+parsed.reduce((n,x)=>n+x.weightBp,0);
 if(total>10000)throw Error('Imported step weights exceed 100% with existing steps');
 const order=current.at(-1)?.order||0;
 const added=parsed.map((x,i)=>({id:id(),projectId,title:x.title,weightBp:x.weightBp,doneBp:x.doneBp,
   order:order+i+1,createdAt:now()}));
 s.projectProgressSteps.push(...added);
 return added;
}
export function distributeProgressWeights(s,projectId){
 const steps=projectSteps(s,projectId);
 if(!steps.length)throw Error('Add at least one progress step first');
 const each=Math.floor(10000/steps.length),remainder=10000-each*steps.length;
 steps.forEach((x,i)=>{x.weightBp=each+(i<remainder?1:0);x.updatedAt=now();});
 return progressSnapshot(s,projectId);
}
export function updateStepCompletion(s,{projectId,stepId,completion}){
 const step=projectSteps(s,projectId).find(x=>x.id===stepId);
 if(!step)throw Error('Progress step not found');
 step.doneBp=basis(completion,'Completion');step.updatedAt=now();
 return step;
}

progress-ui-v043.mjs:
/* Weighted progress UI. At most 50 steps visible at once for large projects. */
import {projectSteps,progressSnapshot,saveProgressStep,archiveProgressStep,
 generateProgressSteps,importProgressSteps,distributeProgressWeights,updateStepCompletion} from './progress-v043.mjs';
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&#39;'}[c]));
const pct=x=>(Number(x)||0).toFixed(2).replace(/\.?0+$/,'');
const btn=(title,action,attrs='',color='')=>'<button type="button" data-action="'+action+'" '+attrs+' class="btn small '+color+'">'+h(title)+'</button>';
export function renderProjectProgress(s,ui,projectId){
 const summary=progressSnapshot(s,projectId),steps=projectSteps(s,projectId);
 const filter=String(ui.progressQuery||'').trim().toLowerCase();
 const found=filter?steps.filter(x=>x.title.toLowerCase().includes(filter)):steps;
 const perPage=40,maxPage=Math.max(0,Math.ceil(found.length/perPage)-1);
 const page=Math.min(Math.max(0,Number(ui.progressPage)||0),maxPage);ui.progressPage=page;
 const paged=found.slice(page*perPage,(page+1)*perPage);
 const rows=paged.map(x=>'<tr><td colspan="4"><form class="v43-progress-edit" data-form="v43-step-edit">'+
  '<input type="hidden" name="projectId" value="'+h(projectId)+'"><input type="hidden" name="stepId" value="'+h(x.id)+'">'+
  '<label>Step<input name="title" maxlength="140" required aria-label="Progress step title" value="'+h(x.title)+'"></label>'+
  '<label>Weight %<input name="weight" aria-label="Weight percent" type="number" step="0.01" min="0" max="100" required value="'+pct(x.weightBp/100)+'"></label>'+
  '<label>Done %<input name="completion" aria-label="Completion percent" type="number" step="0.01" min="0" max="100" required value="'+pct(x.doneBp/100)+'"></label>'+
  '<div class="v43-table-actions"><button type="submit" class="btn small primary">Save</button>'+
  btn(x.doneBp===10000?'Reset':'Done','v43-progress-toggle','data-id="'+h(x.id)+'" data-project="'+h(projectId)+'"')+
  btn('Remove','v43-progress-remove','data-id="'+h(x.id)+'" data-project="'+h(projectId)+'"','danger')+
  '</div></form></td></tr>').join('');
 const removed=s.projectProgressSteps.filter(x=>x.projectId===projectId&&x.archivedAt);
 return '<div class="v43-progress-workspace"><div class="v43-title-row"><div><h2>Manual project progress</h2>'+
  '<p>Define exactly which steps count toward project completion and how much each one is worth.</p></div>'+
  '<strong class="v43-progress-big">'+pct(summary.earned)+'%</strong></div>'+
  '<div class="v43-progress-track"><span style="width:'+summary.earned+'%"></span></div>'+
  '<div class="v43-progress-stats"><span>'+summary.completed+' / '+summary.count+' completed</span>'+
  '<span>'+pct(summary.weightTotal)+'% of weights assigned</span>'+
  '<span class="'+(summary.fullyWeighted?'v43-good':'v43-warn')+'">'+(summary.fullyWeighted?'Weights total 100%':pct(summary.unassigned)+'% weight unassigned')+'</span></div>'+
  '<div class="v43-progress-setup"><form data-form="v43-step-add" class="v43-inline-form">'+
  '<input name="projectId" value="'+h(projectId)+'" type="hidden">'+
  '<label>New step title<input name="title" required maxlength="140" placeholder="e.g. Finalise cockpit drawings"></label>'+
  '<label>Weight (%)<input name="weight" required type="number" min="0" max="100" step="0.01" value="0"></label>'+
  '<button class="btn primary" type="submit">Add step</button></form>'+
  '<form data-form="v43-step-generate" class="v43-inline-form">'+
  '<input name="projectId" value="'+h(projectId)+'" type="hidden">'+
  '<label>Generate steps<input name="count" type="number" required min="1" max="1000" value="10"></label>'+
  '<button type="submit" class="btn">Create placeholders</button></form>'+
  '<div class="v43-progress-row">'+btn('Distribute weights equally','v43-progress-equal','data-project="'+h(projectId)+'"','')+
  '<span>Use equal weighting as a starting point, then edit each step to suit your project. Supports up to 1,000 steps.</span></div>'+
  '<form data-form="v43-step-import" class="v43-progress-import">'+
  '<input name="projectId" type="hidden" value="'+h(projectId)+'">'+
  '<label>Paste a step list (one per line). Optional: title | weight % | completion %<textarea name="lines" rows="3" placeholder="Design concept | 10 | 100&#10;Procure components | 25 | 0"></textarea></label>'+
  '<button class="btn" type="submit">Import steps</button></form></div>'+
  '<div class="v43-progress-list-head"><h3>Progress steps ('+found.length+')</h3>'+
  '<input data-filter="v43-progress-search" value="'+h(ui.progressQuery||'')+'" placeholder="Search steps" aria-label="Search progress steps"></div>'+
  '<div class="v43-scroll"><table class="v43-table"><thead><tr><th>Step</th><th>Weight %</th><th>Done %</th><th>Actions</th></tr></thead><tbody>'+
  (rows||'<tr><td colspan="4">No steps yet. Add your milestones above.</td></tr>')+'</tbody></table></div>'+
  '<div class="v43-pagination">'+btn('Previous','v43-progress-prev','','')+
  '<span>Page '+(page+1)+' / '+(maxPage+1)+'</span>'+btn('Next','v43-progress-next','','')+'</div>'+
  (removed.length?'<details class="v43-restore"><summary>'+removed.length+' removed progress steps</summary>'+
    removed.map(x=>'<div>'+h(x.title)+' '+btn('Restore','v43-progress-restore','data-id="'+h(x.id)+'" data-project="'+h(projectId)+'"')+'</div>').join('')+'</details>':'')+
  '<p class="v43-note">Completion = sum of each step’s percentage weight multiplied by its completion %. If weights total less than 100%, the remaining share is unearned. The original Work Register and Gantt are unchanged; the customer portal is not automatically updated.</p></div>';
}
export function handleProgressForm(s,ui,form){
 const fd=new FormData(form),get=x=>String(fd.get(x)||'').trim(),pid=get('projectId');
 switch(form.dataset.form){
  case 'v43-step-add':return saveProgressStep(s,{projectId:pid,title:get('title'),weight:get('weight'),completion:0});
  case 'v43-step-edit':return saveProgressStep(s,{projectId:pid,id:get('stepId'),title:get('title'),weight:get('weight'),completion:get('completion')});
  case 'v43-step-generate':return generateProgressSteps(s,{projectId:pid,count:get('count')});
  case 'v43-step-import':return importProgressSteps(s,{projectId:pid,lines:get('lines')});
  default:throw Error('Unknown progress form');
 }
}
export function handleProgressAction(s,ui,el,confirmFn=()=>true){
 const pid=el.dataset.project||ui.project,stepId=el.dataset.id;
 switch(el.dataset.action){
  case 'v43-progress-equal':if(confirmFn('Reallocate all progress step weights evenly to exactly 100%?'))return distributeProgressWeights(s,pid);return null;
  case 'v43-progress-toggle':{const row=projectSteps(s,pid).find(x=>x.id===stepId);if(!row)throw Error('Progress step unavailable');return updateStepCompletion(s,{projectId:pid,stepId,completion:row.doneBp===10000?0:100});}
  case 'v43-progress-remove':if(confirmFn('Remove this step from active progress? Its weight will become unassigned.'))return archiveProgressStep(s,{projectId:pid,stepId});return null;
  case 'v43-progress-restore':return archiveProgressStep(s,{projectId:pid,stepId,restore:true});
  case 'v43-progress-prev':ui.progressPage=Math.max(0,(ui.progressPage||0)-1);return 'ui';
  case 'v43-progress-next':ui.progressPage=(ui.progressPage||0)+1;return 'ui';
  default:throw Error('Unknown progress action');
 }
}

external-work-v043.mjs:
/* External subcontractor/production handoff timeline.
   All events are locally recorded by a user; the tool cannot verify fault or causes. */
const createId=p=>p+'-'+Math.random().toString(36).slice(2,12);
const stamp=()=>new Date().toISOString();
const required=(v,kind)=>{const s=String(v||'').trim();if(!s||s.length>180)throw Error(kind+' is required (max 180 characters)');return s;};
export const validISODate=x=>!x||(/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x+'T12:00:00Z'))&&new Date(x+'T12:00:00Z').toISOString().slice(0,10)===x);
const date=v=>{const x=String(v||'').trim();if(!validISODate(x))throw Error('Enter a valid YYYY-MM-DD date');return x;};
export const daysBetween=(a,b)=>{if(!a||!b)return null;return Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000)};
const nowDate=()=>stamp().slice(0,10);
function audit(s,routeId,stageId,event,detail='',old={},next={}){
 s.externalWorkEvents.unshift({id:createId('ev'),routeId,stageId:event==='Route created'?null:stageId,
  event,detail:String(detail||'').slice(0,1200),previous:old,next,at:stamp(),recordedBy:'Sim-Worx Demo'});
}
export function ensureExternalWork(s){s.externalWorkRoutes??=[];s.externalWorkEvents??=[];return s}
const getProject=(s,id)=>{
 const p=s.projects?.find(x=>x.id===id&&!x.archivedAt);if(!p)throw Error('Project not found');return p;
};
export const activeRoutes=(s,projectId)=>{ensureExternalWork(s);return s.externalWorkRoutes.filter(x=>!x.archivedAt&&(!projectId||x.projectId===projectId))};
const getRoute=(s,id)=>{ensureExternalWork(s);const v=s.externalWorkRoutes.find(x=>x.id===id&&!x.archivedAt);if(!v)throw Error('External work package unavailable');return v};
const getStage=(r,id)=>{const v=r.stages.find(x=>x.id===id&&!x.archivedAt);if(!v)throw Error('Stage not found');return v;};
export const activeStages=route=>route.stages.filter(x=>!x.archivedAt).sort((a,b)=>a.order-b.order);
export function createExternalRoute(s,{projectId,title,partId,assemblyId,quantity,requiredBy,notes}){
 ensureExternalWork(s);getProject(s,projectId);
 if(partId&&!s.parts.some(x=>x.id===partId&&!x.archivedAt))throw Error('Part not found');
 if(assemblyId&&!s.assemblies?.some(x=>x.id===assemblyId&&x.projectId===projectId&&!x.archivedAt))throw Error('Assembly must belong to the selected project');
 const qty=Number(quantity||1);if(!Number.isSafeInteger(qty)||qty<1)throw Error('Quantity must be a positive whole number');
 const item={id:createId('work'),projectId,title:required(title,'Work package title'),partId:partId||null,
   assemblyId:assemblyId||null,quantity:qty,requiredBy:date(requiredBy),notes:String(notes||'').slice(0,1000),
   stages:[],createdAt:stamp()};
 s.externalWorkRoutes.push(item);audit(s,item.id,null,'Route created',item.title);
 return item;
}
export function addExternalStage(s,{routeId,name,type,company,plannedStart,promisedFinish,notes}){
 const r=getRoute(s,routeId);
 const role=type==='Internal'?'Internal':'External';
 const supplier=required(company|| (role==='Internal'?'Sim-Worx':''),'Company or responsible team');
 const start=date(plannedStart),finish=date(promisedFinish);
 if(start&&finish&&finish<start)throw Error('Expected return cannot precede planned start');
 const stages=activeStages(r);
 const stage={id:createId('stage'),name:required(name,'Stage name'),type:role,company:supplier,
   order:stages.length?Math.max(...stages.map(x=>x.order))+1:1,plannedStart:start,promisedFinish:finish,
   sentAt:'',returnedAt:'',acceptedAt:'',status:'Planned',notes:String(notes||'').slice(0,1000),
   delayReason:'',createdAt:stamp()};
 r.stages.push(stage);
 audit(s,r.id,stage.id,'Stage created',stage.name,{},{name:stage.name,type:stage.type,company:stage.company,plannedStart:start,promisedFinish:finish});
 return stage;
}
export function updateExternalStage(s,{routeId,stageId,name,type,company,plannedStart,promisedFinish,notes,delayReason}){
 const r=getRoute(s,routeId),st=getStage(r,stageId),old={...st};
 const role=type==='Internal'?'Internal':'External',start=date(plannedStart),finish=date(promisedFinish);
 if(start&&finish&&finish<start)throw Error('Expected finish before planned start');
 const next={name:required(name,'Stage name'),type:role,company:required(company||'Sim-Worx','Company or team'),
   plannedStart:start,promisedFinish:finish,notes:String(notes||'').slice(0,1000),
   delayReason:String(delayReason||'').slice(0,600)};
 Object.assign(st,next);
 audit(s,r.id,st.id,'Stage details updated','Schedule and/or responsibility edited',
  Object.fromEntries(Object.keys(next).map(k=>[k,old[k]])),next);
 return st;
}
export function recordExternalHandoff(s,{routeId,stageId,action,onDate,notes}){
 const route=getRoute(s,routeId),st=getStage(route,stageId),when=date(onDate)||nowDate();
 const comment=String(notes||'').trim().slice(0,1200),prior={status:st.status,sentAt:st.sentAt,returnedAt:st.returnedAt,acceptedAt:st.acceptedAt};
 if(!['send','return','accept','hold','resume'].includes(action))throw Error('Invalid external handoff action');
 if(action==='send'){
  if(st.status!=='Planned')throw Error('Stage must be planned before dispatch');
  const stages=activeStages(route),idx=stages.findIndex(x=>x.id===st.id);
  if(idx>0&&stages[idx-1].status!=='Accepted')throw Error('The previous handoff must be accepted first');
  st.sentAt=when;st.status='With supplier';
 }else if(action==='return'){
  if(st.status!=='With supplier'&&st.status!=='On hold')throw Error('Stage is not currently with supplier');
  if(st.sentAt&&when<st.sentAt)throw Error('Return date precedes dispatch');
  st.returnedAt=when;st.status='Returned · inspect';
 }else if(action==='accept'){
  if(st.status!=='Returned · inspect')throw Error('Inspect received work before accepting it');
  if(st.returnedAt&&when<st.returnedAt)throw Error('Acceptance date precedes receipt');
  st.acceptedAt=when;st.status='Accepted';
 }else if(action==='hold'){
  if(st.status!=='With supplier')throw Error('Only work currently with supplier can be placed on hold');
  if(!comment)throw Error('Record a factual hold note');st.status='On hold';
 }else if(action==='resume'){
  if(st.status!=='On hold')throw Error('Stage must be on hold first');
  st.status='With supplier';
 }
 audit(s,route.id,st.id,{send:'Sent to company',return:'Returned to Sim-Worx',accept:'Inspected and accepted',
  hold:'Placed on hold',resume:'Hold cleared'}[action],comment,prior,
  {status:st.status,sentAt:st.sentAt,returnedAt:st.returnedAt,acceptedAt:st.acceptedAt,date:when});
 return st;
}
export function archiveExternalRoute(s,routeId){
 const r=getRoute(s,routeId);r.archivedAt=stamp();
 audit(s,r.id,null,'Work package archived','Historical events remain preserved');return r;
}
export function externalStageTiming(stage,today=nowDate()){
 const end=stage.returnedAt||((stage.status==='With supplier'||stage.status==='On hold')?today:'');
 const elapsed=stage.sentAt&&end?Math.max(0,daysBetween(stage.sentAt,end)):null;
 const overdue=stage.promisedFinish&&(stage.returnedAt||['With supplier','On hold'].includes(stage.status))
   ?Math.max(0,daysBetween(stage.promisedFinish,stage.returnedAt||today)):0;
 return {elapsedDays:elapsed,overdueDays:overdue,finishedLate:!!(stage.returnedAt&&overdue>0),
   activeOverdue:!!(!stage.returnedAt&&['With supplier','On hold'].includes(stage.status)&&overdue>0),
   missingPromise:!stage.promisedFinish};
}
export function externalRouteSummary(s,projectId,today=nowDate()){
 const routes=activeRoutes(s,projectId),all=routes.flatMap(activeStages);
 const late=all.map(st=>({...st,timing:externalStageTiming(st,today)})).filter(x=>x.timing.overdueDays>0);
 return {routes:routes.length,stages:all.length,atSuppliers:all.filter(x=>['With supplier','On hold'].includes(x.status)).length,
  waitingInspection:all.filter(x=>x.status==='Returned · inspect').length,late,
  completedRoutes:routes.filter(r=>activeStages(r).length&&activeStages(r).every(x=>x.status==='Accepted')).length};
}
export function externalWorkTimeline(s,routeId,today=nowDate()){
 const route=getRoute(s,routeId);
 return {route,stages:activeStages(route).map(st=>({...st,timing:externalStageTiming(st,today)})),
  events:s.externalWorkEvents.filter(e=>e.routeId===routeId).sort((a,b)=>a.at.localeCompare(b.at))};
}
export function exportExternalHistoryCSV(s,projectId,today=nowDate()){
 const header=['Project','Work package','Stage','Responsible company','Stage type','Status','Planned start','Promised finish','Sent to company','Returned to Sim-Worx','Inspected/accepted','Days at stage','Days after promised finish','Delay reason (staff entry)','Notes'];
 const cells=[header];
 for(const route of activeRoutes(s,projectId))
 for(const st of activeStages(route)){
  const t=externalStageTiming(st,today);
  cells.push([projectId,route.title,st.name,st.company,st.type,st.status,st.plannedStart,st.promisedFinish,
  st.sentAt,st.returnedAt,st.acceptedAt,t.elapsedDays??'',t.overdueDays||0,st.delayReason||'',st.notes||'']);
 }
 return cells.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
}

external-ui-v043.mjs:
/* External supplier chain workspace: internal records, no customer auto-publication. */
import {ensureExternalWork,activeRoutes,activeStages,createExternalRoute,addExternalStage,
 updateExternalStage,recordExternalHandoff,archiveExternalRoute,externalRouteSummary,
 externalWorkTimeline,exportExternalHistoryCSV} from './external-work-v043.mjs';
const e=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;','"':'&#39;'}[ch]));
const input=(name,v='',type='text',extra='')=>'<input name="'+e(name)+'" type="'+type+'" value="'+e(v)+'" '+extra+'>';
const sel=(name,rows,value='',extra='')=>'<select name="'+e(name)+'" '+extra+'>'+rows.map(([v,t])=>
