const DAY=86400000;
const asUtc = date => Date.parse(`${date}T12:00:00Z`);
const shiftDate = (date,offset) => new Date(asUtc(date)+offset*DAY).toISOString().slice(0,10);
function flattenedProjectJobs(p){
 const jobs=active(data.tasks).filter(t=>t.projectId===p.id),sections=active(data.sections).filter(s=>s.projectId===p.id);
 const output=[];
 const traverse=(t,code,depth,seen=new Set())=>{if(seen.has(t.id)||depth>12)return;output.push({task:t,code,depth});const next=new Set([...seen,t.id]);jobs.filter(child=>child.parentId===t.id).forEach((child,i)=>traverse(child,`${code}.${i+1}`,depth+1,next));};
 sections.forEach((sec,i)=>{output.push({section:sec,code:`${i+1}.0`,depth:0});jobs.filter(t=>t.sectionId===sec.id&&(!t.parentId||!jobs.some(x=>x.id===t.parentId))).forEach((t,k)=>traverse(t,`${i+1}.${k+1}`,0));});
 return output;
}
