 const anchor=shiftDate(today(),-14+ui.ganttOffset*28);const WEEKS=16;const spanDays=WEEKS*7;
 const end=shiftDate(anchor,spanDays),ax=asUtc(anchor),width=100;
 const xPos=date=>100*((asUtc(date)-ax)/DAY)/spanDays;
 const weeks=Array.from({length:WEEKS},(_,i)=>shiftDate(anchor,i*7));
 const todayX=xPos(today());
 const header=`<div class="gantt-row gantt-head"><div class="gantt-label">WBS / Department job</div><div class="gantt-axis">${weeks.map(w=>`<div>${day(w).replace(/,? \d{4}/,'')}</div>`).join('')}</div></div>`;
 const content=jobs.map(row=>{
  if(row.section)return `<div class="gantt-row gantt-section"><div class="gantt-label">${e(row.code)} · ${e(row.section.name)}</div><div class="gantt-grid"></div></div>`;
  const t=row.task,start=t.start||'',due=t.due||'',base=p.baseline?.jobs?.[t.id],deps=predecessorIds(t),conflict=summary.conflicts.some(x=>x.jobId===t.id);
