  else if(due){const mark=xPos(due);if(mark>=0&&mark<=100)bar=`<div class="gantt-marker" style="left:${mark}%" title="Finish ${day(due)} — add a start date"></div>`;}
  let baseline='';if(base?.start&&base?.due){const left=Math.max(0,xPos(base.start)),right=Math.min(100,xPos(shiftDate(base.due,1)));if(right>left)baseline=`<div class="gantt-baseline" style="left:${left}%;width:${Math.max(0.5,right-left)}%" title="Original baseline ${day(base.start)}–${day(base.due)}"></div>`;}
  return `<div class="gantt-row"><div class="gantt-label gantt-job" style="padding-left:${14+row.depth*17}px"><span class="mono">${e(row.code)}</span><button data-action="edit-task" data-id="${e(t.id)}" title="Edit job plan">${e(t.title)}</button><small>${e(t.department)}${deps.length?` · ${deps.length} predecessor${deps.length>1?'s':''}`:''}</small></div><div class="gantt-grid" data-action="edit-task" data-id="${e(t.id)}" title="Edit ${e(t.title)}">${baseline}${bar}${!start?'<span class="gantt-unscheduled">Plan start</span>':''}${todayX>=0&&todayX<=100?`<span class="gantt-today" style="left:${todayX}%"></span>`:''}</div></div>`;
 }).join('');
 const alerts=[...summary.conflicts.map(x=>`<div class="plan-warning">${ico('clock',15)} <b>Dependency clash</b> · ${e(x.job)} starts before ${e(x.predecessor)} finishes.</div>`),...(summary.overdue.length?[`<div class="plan-warning">${ico('bell',15)} <b>${summary.overdue.length} past-due jobs</b> are not marked complete.</div>`]:[])];
 return `<div class="planning-intro"><div><strong>Baseline & dependency schedule</strong><p>Manual planned dates · finish-to-start logic · original baselines remain visible as dotted bars.</p></div><div class="row-actions">${button('◀ 4 weeks','gantt-prev','small')}${button('Today','gantt-today','small')}${button('4 weeks ▶','gantt-next','small')}${summary.unscheduled.length?button('Fill example dates','fill-demo-dates','small',`data-id="${p.id}"`):''}${button('Capture baseline','capture-baseline','small primary',`data-id="${p.id}"`)}</div></div><div class="plan-kpis"><div><strong>${summary.planned}/${summary.total}</strong><span>Jobs with start and finish</span></div><div><strong>${summary.unscheduled.length}</strong><span>Unscheduled jobs</span></div><div><strong>${summary.conflicts.length}</strong><span>Dependency clashes</span></div><div><strong>${summary.slipped.length}</strong><span>Finish dates past baseline</span></div></div>${p.baseline?`<div class="baseline-note">${ico('check',14)} Baseline captured ${day(p.baseline.capturedAt)} · dotted bars show original plan. Capture again only when you intentionally rebaseline.</div>`:''}<div class="gantt-scroll"><div class="gantt-chart">${header}${content}</div></div><div class="gantt-legend"><span><i class="gantt-key planned"></i> Planned work</span><span><i class="gantt-key baseline"></i> Baseline</span><span><i class="gantt-key completion"></i> Completed</span><span><i class="gantt-key issue"></i> Clash</span><span>◆ finish only</span></div>${alerts.slice(0,8).join('')}<p class="planning-foot">Scheduling conflicts are warnings rather than automatic date changes. Critical-path calculations and resource levelling require a later verified planning engine.</p>`;
