function openModal(type,details={}){ui.modal={type,...details};render()}
function closeModal(){ui.modal=null;render()}
function changePage(page){ui.page=page;ui.modal=null;render()}
function exportWbs(projectId){
  const project=findProject(projectId);if(!project)throw Error('Project not found');
  const headings=['WBS','Section','Job','Department','Assigned to','Priority','Status','Planned start','Planned finish','Predecessor jobs'];
  const rows=[headings];active(data.sections).filter(s=>s.projectId===project.id).forEach((sec,i)=>{
    rows.push([`${i+1}.0`,sec.name,'','','','','','','','']);
    const visited=new Set();let index=0;
    const visit=(task,wbs,depth)=>{if(visited.has(task.id)||depth>12)return;visited.add(task.id);
      rows.push([wbs,sec.name,task.title,task.department,task.assignee,task.priority,task.status,task.start||'',task.due,predecessorIds(task).map(id=>data.tasks.find(t=>t.id===id)?.title||id).join('; ')]);
      active(data.tasks).filter(t=>t.parentId===task.id).forEach((child,k)=>visit(child,`${wbs}.${k+1}`,depth+1));
    };
    active(data.tasks).filter(t=>t.sectionId===sec.id&&!t.parentId).forEach(t=>visit(t,`${i+1}.${++index}`,0));
  });
  const csv=rows.map(row=>row.map(value=>'"'+String(value??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));
  const a=document.createElement('a');a.href=url;a.download=`${project.code}-WBS.csv`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
}
function handleAction(el){const action=el.dataset.action,id=el.dataset.id;
 if(['publish','withdraw-update','invite-modal','approval-decision','client-send-message'].includes(action)){
   toast('Customer-facing publishing and invitations are disabled in this staff-only release.',true);return;
 }
 if(action?.startsWith('workspace-')){try{handleWorkspaceAction(action)}catch(err){toast(String(err.message||err),true)}return;}
 if(!workspaceManager.status().signedIn)return;
 if(action?.startsWith('mfg-')){try{handleManufacturingAction(data,ui,el,window.confirm);persist();render();toast('Manufacturing record updated and queued for encrypted saving');}catch(err){toast(err.message||'Manufacturing action failed',true)}return;}

  if(action==='v42-edit-master'){ui.partReturnProject=ui.project;openModal('part',{id});return;}
 if(action?.startsWith('v41-')||action?.startsWith('v42-material-')||action==='v42-new-part'||action==='v43-quick-part-cancel'){
   try{
     if(action==='v41-backup'){
       const payload=createWorkspaceBackup(data),url=URL.createObjectURL(new Blob([payload],{type:'application/json'}));
       const link=document.createElement('a');link.href=url;link.download='SimWorx_Project_Hub_Backup_V0.4.3_'+today()+'.json';
       document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
       toast('JSON workspace backup downloaded · keep it private');return;
     }
     if(action==='v41-restore'){document.getElementById('v41-restore-file')?.click();return;}
     const changed=handleMaterialsAction(data,ui,el,window.confirm);
     if(changed!=='dom'){persist();render();toast('Procurement updated locally');}
   }catch(err){toast(err.message||'Procurement action failed',true)}
   return;
 }


 if(action?.startsWith('v43-progress-')||action?.startsWith('v43-external-')){
   try{
     const outcome=action.startsWith('v43-progress-')?
       handleProgressAction(data,ui,el,window.confirm):
       handleExternalAction(data,ui,el,window.confirm);
     if(outcome&&typeof outcome==='object'&&outcome.download!==undefined){
       const url=URL.createObjectURL(new Blob(['\ufeff'+outcome.download],{type:'text/csv;charset=utf-8'}));
       const link=document.createElement('a');link.href=url;link.download=outcome.name;
       document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
     }else if(outcome!==null&&outcome!=='ui')persist();
     render();
   }catch(err){toast(err.message||'Unable to update project tracking',true)}
   return;
 }

 try{switch(action){
  case 'nav':if(id==='purchasing')ui.procurementProject=ui.project;else if(id==='projects')ui.projectTab='focus';changePage(id);break;
  case 'project-open':ui.page='projects';ui.project=id;ui.projectTab='focus';ui.procurementProject=id;ui.showProjectList=false;render();document.getElementById('project-detail')?.scrollIntoView({behavior:'smooth',block:'start'});break;
  case 'project-tab':ui.projectTab=id;render();break;
  case 'v43-purchasing':ui.procurementProject=ui.project;ui.page='purchasing';ui.materialPO=null;render();break;
  case 'v43-onboard-company':ui.page='customers';openModal('customer');break;
  case 'v42-toggle-project-list':ui.showProjectList=!ui.showProjectList;render();break;
  case 'client-tab':ui.clientTab=id;render();break;
  case 'task-board':ui.taskView='board';render();break;
  case 'task-list':ui.taskView='list';render();break;
  case 'department-open':ui.dept=id;ui.page='tasks';render();break;
  case 'open-project-modal':openModal('project');break;
  case 'edit-project':openModal('project',{id});break;
  case 'edit-customer':openModal('customer',{id});break;
  case 'edit-task':openModal('task',{id});break;
  case 'add-subtask':{const t=data.tasks.find(x=>x.id===id);if(t)openModal('task',{project:t.projectId,parent:t.id,section:t.sectionId});break;}
